window.ARTICLES = [
  {id:'vieja',img:'recinto',gallery:['plazaarmas','santiago','conventico','trapana','faro'],read:4,route:4,places:[101,102,97,93,98,144,99],
   t:{
    es:{cat:'Historia',title:'Melilla la Vieja: cinco siglos sobre la roca',excerpt:'La ciudadela que se asoma al Mediterráneo: murallas, cuevas y miradores a un paseo del centro.',
      body:['Conocida por los melillenses como «El Pueblo», Melilla la Vieja es el conjunto fortificado que se levanta sobre un promontorio rocoso junto al puerto. Su historia moderna arranca en 1497 y, con los siglos, se fueron sumando cuatro recintos amurallados que hoy se recorren a pie.','Se entra por la Puerta de Santiago, presidida por el escudo de Carlos V, hasta la Plaza de Armas. Desde allí, los túneles de las Cuevas del Conventico bajan hacia el mar, y los aljibes y baluartes cuentan cómo se vivía dentro de los muros.','Ven a última hora de la tarde: la luz dorada sobre la piedra y las vistas del puerto desde los baluartes son uno de los mejores recuerdos que te llevarás de Melilla.']},
    en:{cat:'History',title:'Old Melilla: five centuries on the rock',excerpt:'The citadel overlooking the Mediterranean: walls, caves and viewpoints a short walk from the centre.',
      body:['Known locally as “El Pueblo”, Old Melilla is the fortified complex rising on a rocky headland next to the port. Its modern history begins in 1497, and over the centuries four walled enclosures were added that you can now explore on foot.','Enter through the Gate of Santiago, crowned by the coat of arms of Charles V, and on to the Parade Square. From there, the tunnels of the Conventico Caves lead down towards the sea, while cisterns and bastions tell how life was lived inside the walls.','Come in the late afternoon: the golden light on the stone and the views of the harbour from the bastions are among the best memories you will take home.']},
    fr:{cat:'Histoire',title:'Melilla la Vieja : cinq siècles sur le rocher',excerpt:'La citadelle face à la Méditerranée : remparts, grottes et belvédères à deux pas du centre.',
      body:['Surnommée « El Pueblo » par les habitants, Melilla la Vieja est l’ensemble fortifié qui s’élève sur un promontoire rocheux près du port. Son histoire moderne commence en 1497 et, au fil des siècles, quatre enceintes ont été ajoutées ; on les parcourt aujourd’hui à pied.','On entre par la Porte de Santiago, ornée des armoiries de Charles Quint, jusqu’à la Place d’Armes. De là, les tunnels des grottes du Conventico descendent vers la mer, et citernes et bastions racontent la vie à l’intérieur des murs.','Venez en fin d’après-midi : la lumière dorée sur la pierre et la vue sur le port depuis les bastions sont parmi les plus beaux souvenirs de Melilla.']},
    ar:{cat:'تاريخ',title:'مليلية القديمة: خمسة قرون على الصخرة',excerpt:'القلعة المطلة على المتوسط: أسوار وكهوف ومطلات على بعد خطوات من المركز.',
      body:['يسميها أهل المدينة «إل بويبلو»، ومليلية القديمة هي المجمع المحصن القائم على رأس صخري بجوار الميناء. يبدأ تاريخها الحديث عام 1497، وعلى مر القرون أضيفت أربعة أسوار يمكن اليوم التجول فيها سيرًا على الأقدام.','تدخل من بوابة سانتياغو التي يعلوها شعار كارلوس الخامس وصولًا إلى ساحة السلاح. ومن هناك تنزل أنفاق كهوف الكونفنتيكو نحو البحر، وتحكي الصهاريج والأبراج كيف كانت الحياة داخل الأسوار.','تعال في آخر النهار: الضوء الذهبي على الحجر ومنظر الميناء من الأبراج من أجمل الذكريات التي ستحملها من مليلية.']}
   }},
  {id:'modernismo',img:'melul',gallery:['asamblea','reconquista','casino','mercadoreal','plazaespana'],read:4,route:1,places:[104,111,106,107,108,109,110],
   t:{
    es:{cat:'Arquitectura',title:'El Triángulo de Oro modernista',excerpt:'Una de las mayores concentraciones de arquitectura modernista de España, a cielo abierto.',
      body:['A principios del siglo XX Melilla creció fuera de sus murallas, y lo hizo con fachadas llenas de curvas, flores y balcones de forja. El resultado es el llamado Triángulo de Oro, el Ensanche que parte de la Plaza de España.','El gran nombre es Enrique Nieto, arquitecto catalán que dejó en la ciudad decenas de edificios, como el Palacio de la Asamblea o el edificio La Reconquista. Mira hacia arriba: los mejores detalles están en las cornisas y los chaflanes.','Recorre la ruta con calma y con la audioguía, y haz una pausa en alguna terraza del centro para disfrutar del ambiente.']},
    en:{cat:'Architecture',title:'The modernist Golden Triangle',excerpt:'One of the largest concentrations of modernist architecture in Spain, in the open air.',
      body:['In the early 20th century Melilla grew beyond its walls, with façades full of curves, flowers and wrought-iron balconies. The result is the so-called Golden Triangle, the city extension that starts at Plaza de España.','The big name is Enrique Nieto, a Catalan architect who left dozens of buildings here, such as the Assembly Palace and La Reconquista building. Look up: the best details are on the cornices and corners.','Take the route slowly with the audio guide, and stop at a café terrace in the centre to enjoy the atmosphere.']},
    fr:{cat:'Architecture',title:'Le Triangle d’Or moderniste',excerpt:'L’une des plus grandes concentrations d’architecture moderniste d’Espagne, à ciel ouvert.',
      body:['Au début du XXe siècle, Melilla s’est étendue hors de ses remparts avec des façades pleines de courbes, de fleurs et de balcons en fer forgé. C’est le « Triangle d’Or », le quartier qui part de la Plaza de España.','Le grand nom est Enrique Nieto, architecte catalan qui a laissé des dizaines d’édifices, comme le Palais de l’Assemblée ou l’immeuble La Reconquista. Levez les yeux : les plus beaux détails sont sur les corniches et les angles.','Parcourez le circuit tranquillement avec l’audioguide et faites une pause en terrasse dans le centre.']},
    ar:{cat:'عمارة',title:'المثلث الذهبي الحداثي',excerpt:'من أكبر تجمعات العمارة الحداثية في إسبانيا، في الهواء الطلق.',
      body:['في أوائل القرن العشرين امتدت مليلية خارج أسوارها بواجهات مليئة بالمنحنيات والزهور والشرفات الحديدية. والنتيجة هي ما يُعرف بالمثلث الذهبي، الحي الذي ينطلق من ساحة إسبانيا.','الاسم الأبرز هو إنريكي نييتو، المهندس الكتالوني الذي ترك عشرات المباني مثل قصر الجمعية ومبنى لا ريكونكيستا. ارفع نظرك: أجمل التفاصيل في الأفاريز والزوايا.','امشِ في المسار على مهل مع الدليل الصوتي، وتوقف في أحد المقاهي وسط المدينة للاستمتاع بالأجواء.']}
   }},
  {id:'culturas',img:'sagrado',gallery:['mezquita','sagrado','plazaespana'],read:3,route:2,places:[84,85,86,87,88,89],
   t:{
    es:{cat:'Culturas',title:'Una ciudad, cuatro culturas',excerpt:'Iglesias, mezquitas, sinagogas y un templo hindú conviven a pocas calles de distancia.',
      body:['Melilla es un lugar de encuentro: cristianos, musulmanes, judíos e hindúes comparten calles, fiestas y cocina desde hace generaciones.','La Ruta de los Templos une en un paseo la Iglesia del Sagrado Corazón, la Mezquita Central, la Sinagoga Or Zoruah y el Templo Hindú, cada uno con su propia historia y arquitectura.','Respeta los horarios de culto y viste de forma adecuada al entrar. Para visitas con guía, pregunta en la Oficina de Turismo.']},
    en:{cat:'Cultures',title:'One city, four cultures',excerpt:'Churches, mosques, synagogues and a Hindu temple stand just a few streets apart.',
      body:['Melilla is a meeting place: Christians, Muslims, Jews and Hindus have shared streets, festivals and food for generations.','The Temples Route links the Sacred Heart Church, the Central Mosque, the Or Zoruah Synagogue and the Hindu Temple in one walk, each with its own history and architecture.','Respect worship times and dress appropriately when entering. For guided visits, ask at the Tourist Office.']},
    fr:{cat:'Cultures',title:'Une ville, quatre cultures',excerpt:'Églises, mosquées, synagogues et un temple hindou à quelques rues les uns des autres.',
      body:['Melilla est un lieu de rencontre : chrétiens, musulmans, juifs et hindous partagent rues, fêtes et cuisine depuis des générations.','La Route des Temples relie en une promenade l’église du Sacré-Cœur, la Mosquée centrale, la synagogue Or Zoruah et le temple hindou, chacun avec son histoire et son architecture.','Respectez les heures de culte et portez une tenue adaptée. Pour une visite guidée, renseignez-vous à l’Office de tourisme.']},
    ar:{cat:'ثقافات',title:'مدينة واحدة، أربع ثقافات',excerpt:'كنائس ومساجد ومعابد يهودية ومعبد هندوسي على بعد شوارع قليلة.',
      body:['مليلية مكان لقاء: يتشارك المسيحيون والمسلمون واليهود والهندوس الشوارع والأعياد والمطبخ منذ أجيال.','يجمع مسار المعابد في نزهة واحدة كنيسة القلب المقدس والمسجد المركزي وكنيس أور زوروا والمعبد الهندوسي، ولكل منها تاريخه وعمارته.','احترم أوقات العبادة وارتدِ ملابس مناسبة عند الدخول. للزيارات المرشدة، اسأل في مكتب السياحة.']}
   }},
  {id:'costa',img:'carabos',gallery:['hipodromo','trapana','puertoatardecer','forcas','faro'],read:3,route:null,places:[74,43],
   beaches:[['Playa de San Lorenzo','carabos'],['Playa de Los Cárabos','carabos'],['Playa del Hipódromo','hipodromo'],['Playa de Trápana','trapana']],
   t:{
    es:{cat:'Costa',title:'Mar, playas y atardeceres',excerpt:'Playas urbanas de arena fina, aguas tranquilas y un puerto que se tiñe de naranja al caer el sol.',
      body:['La bahía de Melilla encadena varias playas urbanas, como San Lorenzo, Los Cárabos o el Hipódromo, con paseo marítimo y servicios en temporada.','Bajo los acantilados de Melilla la Vieja se esconde la pequeña playa de Trápana, y desde el mar se contempla la mejor vista de la ciudadela. Si te apetece navegar, puedes alquilar un barco.','Al atardecer, acércate al puerto: el cielo sobre el cabo de Tres Forcas es el broche perfecto del día.']},
    en:{cat:'Coast',title:'Sea, beaches and sunsets',excerpt:'Fine-sand city beaches, calm waters and a harbour that turns orange at sunset.',
      body:['Melilla’s bay strings together several city beaches, such as San Lorenzo, Los Cárabos and El Hipódromo, with a seafront promenade and seasonal services.','Beneath the cliffs of Old Melilla hides the small Trápana beach, and from the sea you get the best view of the citadel. Fancy sailing? You can rent a boat.','At sunset, head to the harbour: the sky over Cape Tres Forcas is the perfect end to the day.']},
    fr:{cat:'Côte',title:'Mer, plages et couchers de soleil',excerpt:'Plages urbaines de sable fin, eaux calmes et un port qui rougit au coucher du soleil.',
      body:['La baie de Melilla enchaîne plusieurs plages urbaines, comme San Lorenzo, Los Cárabos ou l’Hipódromo, avec promenade et services en saison.','Sous les falaises de Melilla la Vieja se cache la petite plage de Trápana, et depuis la mer on a la plus belle vue sur la citadelle. Envie de naviguer ? Louez un bateau.','Au coucher du soleil, allez au port : le ciel au-dessus du cap des Trois Fourches est la plus belle fin de journée.']},
    ar:{cat:'الساحل',title:'بحر وشواطئ وغروب',excerpt:'شواطئ حضرية برمال ناعمة ومياه هادئة وميناء يتلون بالبرتقالي عند الغروب.',
      body:['يضم خليج مليلية عدة شواطئ حضرية مثل سان لورينثو ولوس كارابوس والهيبودرومو، مع كورنيش وخدمات في الموسم.','تحت منحدرات مليلية القديمة يختبئ شاطئ ترابانا الصغير، ومن البحر ترى أجمل منظر للقلعة. إن رغبت في الإبحار يمكنك استئجار قارب.','عند الغروب توجه إلى الميناء: سماء رأس الثلاث فوركاس هي الختام المثالي لليوم.']}
   }},
  {id:'sabores',img:'pinchitos',gallery:['pescaito','tapas','paella','cafe','medieval'],read:3,route:null,places:[],food:true,
   t:{
    es:{cat:'Gastronomía',title:'Sabores de Melilla',excerpt:'Cocina mediterránea con acento andaluz, bereber y sefardí: de los pinchitos al pescaíto.',
      body:['La mesa melillense mezcla lo mejor de sus culturas: pescado fresco del Mediterráneo, especias del norte de África y la costumbre andaluza del tapeo.','No te vayas sin probar unos pinchitos morunos, pescaíto frito o un té con hierbabuena. La ciudad tiene además cocina marroquí, marisquerías, asadores y fusión.','Abajo tienes una selección de sitios donde comer. Antes de ir, consulta en Google Maps su horario y las reseñas más recientes.']},
    en:{cat:'Food',title:'Flavours of Melilla',excerpt:'Mediterranean cooking with Andalusian, Amazigh and Sephardic accents: from skewers to fried fish.',
      body:['Melilla’s table blends the best of its cultures: fresh Mediterranean fish, North African spices and the Andalusian habit of tapas.','Don’t leave without trying pinchitos morunos (spiced skewers), fried fish or mint tea. The city also offers Moroccan cuisine, seafood, grills and fusion.','Below is a selection of places to eat. Before you go, check opening hours and the latest reviews on Google Maps.']},
    fr:{cat:'Gastronomie',title:'Saveurs de Melilla',excerpt:'Cuisine méditerranéenne aux accents andalou, amazigh et séfarade : des brochettes à la friture.',
      body:['La table de Melilla mêle le meilleur de ses cultures : poisson frais de Méditerranée, épices d’Afrique du Nord et tradition andalouse des tapas.','Ne partez pas sans goûter les pinchitos morunos, la friture de poisson ou un thé à la menthe. La ville propose aussi cuisine marocaine, fruits de mer, grillades et fusion.','Voici une sélection d’adresses. Avant d’y aller, vérifiez horaires et avis récents sur Google Maps.']},
    ar:{cat:'مطبخ',title:'نكهات مليلية',excerpt:'مطبخ متوسطي بلمسات أندلسية وأمازيغية وسفاردية: من الأسياخ إلى السمك المقلي.',
      body:['تمزج مائدة مليلية أفضل ما في ثقافاتها: سمك متوسطي طازج وتوابل شمال إفريقيا وعادة التاباس الأندلسية.','لا تغادر دون تذوق أسياخ اللحم المتبلة والسمك المقلي أو الشاي بالنعناع. وفي المدينة أيضًا مطبخ مغربي ومأكولات بحرية ومشاوٍ ومطبخ مبتكر.','إليك مجموعة من أماكن الأكل. قبل الذهاب، تحقق من ساعات العمل وأحدث التقييمات على خرائط Google.']}
   }}
];

